function normalizeMakeupRuntimePhase(raw: unknown): MakeupRuntimePhase | undefined {
  const phase = String(raw ?? "").trim();
  if (!phase)
    return undefined;
  // 旧持久化 pm_pending → venue_pending
  if (phase === "pm_pending")
    return "venue_pending";
  if (
    phase === "placing"
    || phase === "settling"
    || phase === "venue_pending"
    || phase === "rejected_retry"
  ) {
    return phase;
  }
  return undefined;
}

